('11111111-1111-1111-1111-200000000001', '11111111-1111-1111-1111-111111111111', 'Product QA', 'Global', 'Navigation', 'Global navigation supports designer & recruiter dual personas', 'Verify the top-level navigation adapts its primary items based on whether the signed-in user is a Creator or a Recruiter.', 'Creators see Upload/Portfolio/Analytics; Recruiters see Search/Saved/Messages, with shared items (Explore, Settings) always visible.', 'UX Review', 'Automated', 'High', 'Passed', 'Verified across both persona types on staging.', true, now() - interval '8 days'),
('11111111-1111-1111-1111-200000000002', '11111111-1111-1111-1111-111111111111', 'Product QA', 'Global', 'Branding', 'Brand color system enforces dark charcoal + electric-blue palette', 'Validate that surface, text, and accent colors strictly follow the approved CSS custom property tokens.', 'No raw hex colors outside the approved design token set anywhere in the shipped bundle.', 'Visual Spec', 'Automated', 'Medium', 'Passed', 'Token linter passing on latest build.', true, now() - interval '8 days'),
('11111111-1111-1111-1111-200000000003', '11111111-1111-1111-1111-111111111111', 'Product QA', 'Global', 'Accessibility', 'Platform-wide WCAG 2.1 AA contrast compliance', 'Run an automated contrast scan across all primary templates (feed, profile, upload, messaging).', 'All text and interactive elements meet a minimum 4.5:1 contrast ratio.', 'A11y Audit', 'Automated', 'Critical', 'In Progress', 'Two contrast violations remain on the messaging panel.', true, now() - interval '7 days'),
('11111111-1111-1111-1111-200000000004', '11111111-1111-1111-1111-111111111111', 'Product QA', 'Global', 'User Experience', 'Onboarding flow clearly separates Creator vs Recruiter account paths', 'A reviewer walks through fresh sign-up as both a Creator and a Recruiter and evaluates whether the branching choice and resulting setup steps feel intuitive.', 'A first-time user immediately understands which path to choose and is not shown irrelevant setup steps for the other persona.', 'UX Review', 'Human Review', 'High', 'Not Started', '', true, now() - interval '7 days'),
('11111111-1111-1111-1111-200000000005', '11111111-1111-1111-1111-111111111111', 'Product QA', 'Global', 'Functionality', 'Search indexing covers portfolio titles, tags, and creator bios', 'Verify the global search index is updated when a portfolio piece is published or a bio is edited.', 'New or edited content is searchable within 60 seconds of publishing.', 'Functional Spec', 'Automated', 'High', 'Passed', 'Reindex latency averaging 12s in staging.', true, now() - interval '6 days'),
('11111111-1111-1111-1111-200000000006', '11111111-1111-1111-1111-111111111111', 'Product QA', 'Global', 'Performance', 'Homepage feed loads within performance budget on 4G', 'Measure time-to-interactive for the Explore feed under throttled 4G network conditions.', 'Feed reaches interactive state in under 3.5s on a simulated 4G connection.', 'Performance Spec', 'Automated', 'Medium', 'In Progress', 'Currently at 4.1s TTI, image lazy-loading tweak in progress.', true, now() - interval '5 days'),
('11111111-1111-1111-1111-200000000007', '11111111-1111-1111-1111-111111111111', 'Product QA', 'Global', 'Content', 'Platform microcopy consistently addresses both recruiters and creators', 'A reviewer reads through in-app copy, empty states, and tooltips to confirm neutral, persona-appropriate tone.', 'No copy assumes the reader is only a creator or only a recruiter unless on a persona-specific screen.', 'Content Review', 'Human Review', 'Medium', 'Not Started', '', true, now() - interval '5 days'),
