('11111111-1111-1111-1111-200000000008', '11111111-1111-1111-1111-111111111111', 'Page QA', 'Landing Page', 'User Experience', 'Landing hero showcases rotating featured portfolio pieces', 'Verify the marketing landing page hero carousel auto-rotates and pauses on hover/focus.', 'Carousel rotates every 5s, pauses on interaction, and is keyboard navigable.', 'Interaction Spec', 'Automated', 'Medium', 'Passed', '', true, now() - interval '8 days'),
('11111111-1111-1111-1111-200000000009', '11111111-1111-1111-1111-111111111111', 'Page QA', 'Explore Feed', 'Content', 'Explore feed infinite scroll surfaces diverse creative categories', 'Verify the feed algorithm interleaves categories rather than clustering a single category.', 'No more than 3 consecutive posts share the same category tag.', 'Functional Spec', 'Automated', 'High', 'Passed', '', true, now() - interval '8 days'),
('11111111-1111-1111-1111-200000000010', '11111111-1111-1111-1111-111111111111', 'Page QA', 'Project Detail', 'Functionality', 'Project detail page renders multi-image galleries with lazy loading', 'Verify galleries with 10+ images load progressively without blocking the initial render.', 'First 3 images render immediately; remaining images lazy-load as the user scrolls.', 'Performance Spec', 'Automated', 'High', 'Passed', '', true, now() - interval '7 days'),
('11111111-1111-1111-1111-200000000011', '11111111-1111-1111-1111-111111111111', 'Page QA', 'Creator Profile', 'User Experience', 'Creator profile clearly displays hire-me CTA for recruiters', 'A reviewer evaluates whether the "Contact / Hire" CTA is discoverable and clear when viewed by a recruiter account.', 'The CTA is visible above the fold and its purpose is unambiguous without hovering.', 'UX Review', 'Human Review', 'Critical', 'Not Started', '', true, now() - interval '6 days'),
('11111111-1111-1111-1111-200000000012', '11111111-1111-1111-1111-111111111111', 'Page QA', 'Upload Wizard', 'Functionality', 'Upload wizard validates file size/format before submission', 'Verify the client rejects unsupported formats and oversized files before starting an upload.', 'Files over 25MB or not in {jpg, png, webp, mp4} are rejected with a clear inline message before upload begins.', 'Functional Spec', 'Automated', 'High', 'Failed', 'Currently allows 30MB files through; validation threshold misconfigured.', true, now() - interval '5 days'),
('11111111-1111-1111-1111-200000000013', '11111111-1111-1111-1111-111111111111', 'Page QA', 'Recruiter Dashboard', 'Navigation', 'Recruiter dashboard saved-candidates list navigable via sidebar', 'Verify the saved-candidates list is reachable from the recruiter dashboard sidebar and paginates correctly.', 'Sidebar link opens the saved list in under 500ms with correct pagination controls.', 'Functional Spec', 'Automated', 'Medium', 'Not Started', '', true, now() - interval '4 days'),
('11111111-1111-1111-1111-200000000014', '11111111-1111-1111-1111-111111111111', 'Page QA', 'Settings', 'Accessibility', 'Account settings form fields have associated ARIA labels', 'Run an automated accessibility scan on the settings form.', 'Every input has a programmatically associated label detectable by screen readers.', 'A11y Audit', 'Automated', 'Medium', 'Passed', '', true, now() - interval '4 days'),
