('11111111-1111-1111-1111-200000000022', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Upload Wizard', 'Functionality', 'Portfolio upload feature supports batch multi-image upload', 'Verify a creator can select and upload up to 20 images in a single batch with individual progress indicators.', 'Batch of 20 images uploads with per-file progress and a combined success/failure summary.', 'Functional Spec', 'Automated', 'High', 'Passed', '', true, now() - interval '8 days'),
('11111111-1111-1111-1111-200000000023', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Recruiter Dashboard', 'Functionality', 'Recruiter saved-search feature emails weekly digest of new matches', 'Verify saved search criteria trigger a weekly digest email containing newly matching creators.', 'Digest email sent weekly, containing only creators added since the previous digest.', 'Functional Spec', 'Automated', 'Medium', 'In Progress', 'Email template built; scheduler job pending.', true, now() - interval '7 days'),
('11111111-1111-1111-1111-200000000024', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Explore Feed', 'User Experience', 'Follow creator feature updates feed personalization instantly', 'A reviewer follows a creator and evaluates how quickly and clearly the Explore feed reflects that change.', 'Followed creator content appears in a "Following" filter immediately, without requiring a page refresh.', 'UX Review', 'Human Review', 'Medium', 'Not Started', '', true, now() - interval '6 days'),
('11111111-1111-1111-1111-200000000025', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Messages', 'Functionality', 'Direct messaging feature between recruiters and creators', 'Verify recruiters and creators can exchange messages in real time with delivery/read receipts.', 'Messages deliver within 2s and show sent/delivered/read states accurately.', 'Functional Spec', 'Automated', 'Critical', 'Failed', 'Read receipts intermittently fail to update; logged for investigation.', true, now() - interval '5 days'),
('11111111-1111-1111-1111-200000000026', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Upload Wizard', 'Content', 'Portfolio tagging feature suggests relevant skill tags via autocomplete', 'Verify the tag input suggests relevant existing tags as the creator types.', 'Suggestions appear after 2 characters and are ranked by tag popularity.', 'Functional Spec', 'Automated', 'Medium', 'Not Started', '', true, now() - interval '4 days'),
