-- Product QA
('22222222-2222-2222-2222-200000000001', '22222222-2222-2222-2222-222222222222', 'Product QA', 'Global', 'Navigation', 'Sidebar navigation groups Classes, Attendance, Reports for teacher workflows', 'Verify the sidebar organizes core teacher tasks into clear, discoverable groups.', 'Classes, Attendance, and Reports are grouped and reachable within one click from any screen.', 'UX Review', 'Automated', 'High', 'Passed', '', true, now() - interval '5 days'),
('22222222-2222-2222-2222-200000000002', '22222222-2222-2222-2222-222222222222', 'Product QA', 'Global', 'Branding', 'UI color palette maintains calm, classroom-friendly tones across app', 'Validate that the color system avoids harsh or alarming tones outside of explicit warning/error states.', 'Only status colors (red/amber) appear in alert contexts; base UI uses the calm blue/teal palette.', 'Visual Spec', 'Automated', 'Low', 'Passed', '', true, now() - interval '5 days'),
('22222222-2222-2222-2222-200000000003', '22222222-2222-2222-2222-222222222222', 'Product QA', 'Global', 'Accessibility', 'Full app meets WCAG 2.1 AA for low-vision teacher users', 'Run an automated contrast and text-scaling scan across all primary teacher-facing templates.', 'All text meets 4.5:1 contrast and remains legible at 200% browser zoom without horizontal scroll.', 'A11y Audit', 'Automated', 'Critical', 'In Progress', 'Zoom test reveals overflow on the Take Attendance grid.', true, now() - interval '5 days'),
('22222222-2222-2222-2222-200000000004', '22222222-2222-2222-2222-222222222222', 'Product QA', 'Global', 'User Experience', 'New teacher onboarding explains attendance marking in under 3 steps', 'A reviewer completes first-time onboarding as a new teacher account and evaluates clarity and length.', 'A first-time teacher understands how to mark attendance within 3 onboarding steps or fewer, with no confusion observed.', 'UX Review', 'Human Review', 'High', 'Not Started', '', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000005', '22222222-2222-2222-2222-222222222222', 'Product QA', 'Global', 'Functionality', 'Attendance data syncs reliably across offline/online transitions', 'Verify attendance marked while offline correctly syncs once connectivity is restored, without data loss or duplication.', 'Offline-marked attendance queues locally and syncs exactly once when connectivity returns.', 'Functional Spec', 'Automated', 'Critical', 'Failed', 'Duplicate attendance rows observed after reconnect in 2 of 10 test runs.', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000006', '22222222-2222-2222-2222-222222222222', 'Product QA', 'Global', 'Performance', 'App remains responsive with class rosters of 60+ students', 'Measure UI responsiveness (scroll, tap targets) on a class roster stress-tested at 60+ students.', 'Roster scrolling stays above 50fps and tap response stays under 100ms with 60+ students loaded.', 'Performance Spec', 'Automated', 'Medium', 'In Progress', 'Currently 42fps on low-end Android; optimization in progress.', true, now() - interval '3 days'),
('22222222-2222-2222-2222-200000000007', '22222222-2222-2222-2222-222222222222', 'Product QA', 'Global', 'Content', 'Terminology (Present/Absent/Late) consistent across all screens', 'A reviewer audits every screen referencing attendance status to confirm consistent wording.', 'The same three status terms are used verbatim across roster, history, and report screens.', 'Content Review', 'Human Review', 'Medium', 'Not Started', '', true, now() - interval '3 days'),
-- Page QA
('22222222-2222-2222-2222-200000000008', '22222222-2222-2222-2222-222222222222', 'Page QA', 'Class Roster', 'Functionality', 'Class roster page loads full student list with photos under 2s', 'Verify the roster page renders a full class list including student photos within the performance budget.', 'Roster with photos renders in under 2s on a standard 4G connection.', 'Performance Spec', 'Automated', 'High', 'Passed', '', true, now() - interval '5 days'),
('22222222-2222-2222-2222-200000000009', '22222222-2222-2222-2222-222222222222', 'Page QA', 'Take Attendance', 'Functionality', 'Take Attendance page defaults all students to Present for quick marking', 'Verify the daily attendance screen pre-marks all students Present, requiring teachers to only toggle exceptions.', 'All students default to Present on page load; teacher only needs to tap exceptions (Absent/Late).', 'Functional Spec', 'Automated', 'High', 'Passed', '', true, now() - interval '5 days'),
('22222222-2222-2222-2222-200000000010', '22222222-2222-2222-2222-222222222222', 'Page QA', 'Attendance History', 'Content', 'Attendance history page displays monthly calendar heatmap per student', 'Verify the history view renders a color-coded monthly calendar reflecting each day''s attendance status.', 'Calendar heatmap correctly color-codes Present/Absent/Late per day and supports month navigation.', 'Functional Spec', 'Automated', 'Medium', 'In Progress', 'Holiday exclusion styling not yet implemented.', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000011', '22222222-2222-2222-2222-222222222222', 'Page QA', 'Reports', 'Functionality', 'Reports page exports attendance summary as PDF and CSV', 'Verify the reports screen can export the current filtered view in both PDF and CSV formats.', 'Both export formats generate correctly and reflect any active filters (date range, class).', 'Functional Spec', 'Automated', 'High', 'Not Started', '', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000012', '22222222-2222-2222-2222-222222222222', 'Page QA', 'Student Profile', 'User Experience', 'Student profile page surfaces attendance percentage prominently', 'A reviewer evaluates whether a teacher can immediately gauge a student''s attendance standing from the profile page.', 'Attendance percentage is visible without scrolling and its color communicates status (good/at-risk) at a glance.', 'UX Review', 'Human Review', 'Medium', 'Not Started', '', true, now() - interval '3 days'),
('22222222-2222-2222-2222-200000000013', '22222222-2222-2222-2222-222222222222', 'Page QA', 'Parent Notifications', 'Functionality', 'Parent notification page sends SMS alert on 3 consecutive absences', 'Verify the system automatically triggers an SMS alert to the registered guardian after 3 consecutive unexcused absences.', 'SMS is sent within 1 hour of the 3rd consecutive absence being recorded, to the correct guardian contact.', 'Integration Test', 'Automated', 'Critical', 'Failed', 'Alert occasionally fires on the 2nd absence; off-by-one bug logged.', true, now() - interval '3 days'),
('22222222-2222-2222-2222-200000000014', '22222222-2222-2222-2222-222222222222', 'Page QA', 'Login', 'Accessibility', 'Login page form fields are screen-reader labeled and tab-orderable', 'Run an automated accessibility scan on the login form.', 'Username and password fields have programmatic labels and a logical tab order ending at the submit button.', 'A11y Audit', 'Automated', 'Medium', 'Passed', '', true, now() - interval '2 days'),
-- Component QA
('22222222-2222-2222-2222-200000000015', '22222222-2222-2222-2222-222222222222', 'Component QA', 'Take Attendance', 'Functionality', 'Attendance toggle button cycles Present/Absent/Late with single tap', 'Verify the per-student status control cycles through the three states with a single tap and updates instantly.', 'Single tap cycles Present → Absent → Late → Present with immediate visual feedback.', 'Interaction Spec', 'Automated', 'High', 'Passed', '', true, now() - interval '5 days'),
('22222222-2222-2222-2222-200000000016', '22222222-2222-2222-2222-222222222222', 'Component QA', 'Take Attendance', 'User Experience', 'Student avatar list scrolls smoothly with sticky class header', 'Verify the class header (name, date, count) remains visible while the student list scrolls beneath it.', 'Header stays pinned during scroll with no flicker or overlap with list items.', 'Interaction Spec', 'Automated', 'Low', 'Passed', '', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000017', '22222222-2222-2222-2222-222222222222', 'Component QA', 'Take Attendance', 'Accessibility', 'Attendance status icons include text labels, not color alone', 'Verify status indicators are distinguishable without relying solely on color.', 'Each status icon includes a text label or distinct shape, satisfying WCAG 1.4.1 (use of color).', 'A11y Audit', 'Automated', 'Critical', 'In Progress', 'Icons distinct in grayscale; screen reader announcement still generic.', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000018', '22222222-2222-2222-2222-222222222222', 'Component QA', 'Attendance History', 'Functionality', 'Calendar heatmap component correctly highlights holidays as excluded', 'Verify days configured as school holidays render as excluded (non-attendance) rather than absent.', 'Holiday dates render in a neutral "excluded" style and are omitted from attendance percentage calculations.', 'Functional Spec', 'Automated', 'Medium', 'Passed', '', true, now() - interval '3 days'),
('22222222-2222-2222-2222-200000000019', '22222222-2222-2222-2222-222222222222', 'Component QA', 'Take Attendance', 'User Experience', 'Bulk-mark-all-present component includes confirmation before applying', 'A reviewer tests the "Mark All Present" shortcut to confirm it cannot be triggered accidentally.', 'A confirmation step is required before the bulk action overwrites any manually-set statuses.', 'UX Review', 'Human Review', 'Medium', 'Not Started', '', true, now() - interval '2 days'),
('22222222-2222-2222-2222-200000000020', '22222222-2222-2222-2222-222222222222', 'Component QA', 'Class Roster', 'Functionality', 'Search-student component filters roster in real time as typed', 'Verify the roster search box filters the visible list on each keystroke without a submit action.', 'List filters within 150ms of each keystroke, matching name substrings case-insensitively.', 'Interaction Spec', 'Automated', 'Medium', 'Passed', '', true, now() - interval '2 days'),
('22222222-2222-2222-2222-200000000021', '22222222-2222-2222-2222-222222222222', 'Component QA', 'Student Profile', 'Branding', 'Progress ring component (attendance %) uses consistent color thresholds', 'Validate the attendance percentage ring uses the same green/amber/red thresholds everywhere it appears.', 'Thresholds (e.g. 90%+ green, 75-89% amber, <75% red) match across profile, roster, and reports.', 'Visual Spec', 'Automated', 'Low', 'Failed', 'Reports view uses a different amber threshold (80% vs 75%) than profile.', true, now() - interval '1 day'),
-- Feature QA
('22222222-2222-2222-2222-200000000022', '22222222-2222-2222-2222-222222222222', 'Feature QA', 'Class Roster', 'Functionality', 'Bulk attendance import feature parses CSV class rosters correctly', 'Verify a teacher can import an existing class roster via CSV with correct column mapping.', 'CSV import correctly maps name, ID, and contact columns, and flags malformed rows without failing the whole import.', 'Functional Spec', 'Automated', 'High', 'In Progress', 'Column mapping works; duplicate detection not yet implemented.', true, now() - interval '5 days'),
('22222222-2222-2222-2222-200000000023', '22222222-2222-2222-2222-222222222222', 'Feature QA', 'Parent Notifications', 'Functionality', 'Automated absence-alert feature triggers parent SMS/email correctly', 'Verify the notification engine selects the correct channel (SMS/email) per guardian preference and sends accurate content.', 'Correct channel used per preference; message content includes student name, date, and absence count.', 'Integration Test', 'Automated', 'Critical', 'Failed', 'Email channel occasionally used even when SMS is the stated preference.', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000024', '22222222-2222-2222-2222-222222222222', 'Feature QA', 'Class Roster', 'User Experience', 'Substitute-teacher mode feature grants temporary limited class access', 'A reviewer evaluates whether a substitute teacher can be granted quick, clearly-scoped, time-limited access to a single class.', 'Access grant flow takes under 1 minute, clearly states scope and expiry, and substitute cannot access other classes or settings.', 'UX Review', 'Human Review', 'High', 'Not Started', '', true, now() - interval '4 days'),
('22222222-2222-2222-2222-200000000025', '22222222-2222-2222-2222-222222222222', 'Feature QA', 'Reports', 'Functionality', 'Monthly report generation feature aggregates data across all sections', 'Verify the monthly report correctly aggregates attendance across multiple class sections taught by one teacher.', 'Report totals match the sum of individual section totals, with no double-counting of shared students.', 'Functional Spec', 'Automated', 'Medium', 'Passed', '', true, now() - interval '3 days'),
('22222222-2222-2222-2222-200000000026', '22222222-2222-2222-2222-222222222222', 'Feature QA', 'Student Profile', 'Content', 'Leave-request feature lets students/parents submit excused absence notes', 'A reviewer submits a sample excused-absence note as a parent and evaluates the teacher-side review experience.', 'Note submission is simple for a parent, and the teacher can approve/deny with a visible reason trail.', 'UX Review', 'Human Review', 'Medium', 'Not Started', '', true, now() - interval '3 days'),
('22222222-2222-2222-2222-200000000027', '22222222-2222-2222-2222-222222222222', 'Feature QA', 'Class Roster', 'Functionality', 'Multi-class scheduling feature prevents overlapping attendance sessions', 'Verify the system blocks a teacher from opening two attendance sessions for overlapping class times.', 'Attempting to start an overlapping session shows a clear conflict warning and blocks the action.', 'Functional Spec', 'Automated', 'High', 'Skipped', 'Deprioritized pending multi-section scheduling redesign.', true, now() - interval '2 days'),
('22222222-2222-2222-2222-200000000028', '22222222-2222-2222-2222-222222222222', 'Feature QA', 'Reports', 'User Experience', 'Dashboard analytics feature flags at-risk students below 75% attendance', 'A reviewer checks whether the at-risk student list is easy to find and act on from the teacher dashboard.', 'At-risk students (under 75% attendance) are surfaced in a dedicated, sortable list with one-click drill-down to their profile.', 'UX Review', 'Human Review', 'Critical', 'Not Started', '', true, now() - interval '1 day'),
-- Release QA
('22222222-2222-2222-2222-200000000029', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'Functionality', 'Production build passes zero critical console errors on load', 'Verify the production build produces no uncaught console errors across primary teacher templates.', 'Zero critical console errors on Login, Class Roster, Take Attendance, and Reports pages.', 'Smoke Test', 'Automated', 'Critical', 'Passed', '', true, now() - interval '2 days'),
('22222222-2222-2222-2222-200000000030', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'Performance', 'App cold-start time under 3s on low-end Android devices', 'Measure cold-start time on a representative low-end Android test device.', 'App reaches an interactive login screen in under 3s on the reference low-end device.', 'Performance Spec', 'Automated', 'High', 'In Progress', 'Currently 3.4s; investigating bundle size.', true, now() - interval '2 days'),
('22222222-2222-2222-2222-200000000031', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'Accessibility', 'Automated axe-core scan reports zero critical violations pre-release', 'Run axe-core across all primary teacher-facing templates as part of the release checklist.', 'Zero "critical" or "serious" severity violations reported.', 'A11y Audit', 'Automated', 'Critical', 'Passed', '', true, now() - interval '1 day'),
('22222222-2222-2222-2222-200000000032', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Parent Notifications', 'Functionality', 'SMS/email notification integration verified in staging environment', 'Verify the SMS/email provider integration correctly sends and logs notifications in the staging environment.', 'Test notifications sent and logged correctly for both SMS and email channels in staging.', 'Integration Test', 'Automated', 'High', 'Not Started', '', true, now() - interval '1 day'),
('22222222-2222-2222-2222-200000000033', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'User Experience', 'Release notes reviewed for clarity with non-technical teacher audience', 'A reviewer reads the drafted release notes from the perspective of a non-technical teacher user.', 'Release notes are understandable without technical background and lead with the teacher-facing benefit.', 'Content Review', 'Human Review', 'Low', 'Not Started', '', true, now() - interval '20 hours'),
('22222222-2222-2222-2222-200000000034', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'Functionality', 'Data backup/rollback plan validated before term-start rollout', 'Verify a full backup and rollback rehearsal completes successfully before the school-term rollout window.', 'Backup completes and rollback restores prior state without attendance data loss in staging rehearsal.', 'Release Checklist', 'Automated', 'Critical', 'Passed', '', true, now() - interval '18 hours'),
('22222222-2222-2222-2222-200000000035', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Legal', 'Content', 'Student data privacy policy copy reviewed before school district launch', 'A reviewer confirms the privacy policy accurately reflects student data handling (attendance records, contact info) before a district-wide launch.', 'Privacy policy accurately reflects data retention, guardian contact use, and district data-sharing terms.', 'Content Review', 'Human Review', 'High', 'Not Started', '', true, now() - interval '10 hours')
ON CONFLICT (id) DO NOTHING;

